\begin{lemma}\label{lem:Martingale.eq_zero_of_predictable_finiteVariation_bounded_continuous}
  \uses{def:Martingale, def:LocallyBoundedVariationOn, lem:Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
  \lean{MeasureTheory.Martingale.eq_zero_of_predictable_finiteVariation_bounded_continuous}
Let \(M\) be a strongly predictable càdlàg true martingale with \(M_0=0\),
and suppose every path has locally bounded variation.  For every
deterministic time \(t>0\), the bounded-continuous finite-variation bridge
shows that \(M_t=0\) almost surely.
\end{lemma}

\begin{proof}
First reduce to the bounded continuous finite-variation core on a fixed
deterministic horizon.  The local bounded-variation hypothesis gives bounded
variation on \([\bot,t]\) pathwise.  Strong predictability is used only to
remove predictable deterministic jumps: by the preceding past-measurability
increment lemmas, any jump \(M_u-M_{u-}\) that is visible from the predictable
past is zero almost surely.  After this removal, the residual stopped process
has continuous paths on \([\bot,t]\).

Localize the stopped residual once more by deterministic bounds so the stopped
martingale is bounded on \([\bot,t]\).  Apply
Lemma~\ref{lem:Martingale.eq_zero_of_bounded_continuous_finiteVariation_core}
to the bounded continuous finite-variation martingale on this horizon.  Finally
let the localization bound tend to infinity and use the localizing sequence's
almost sure convergence to \(\top\) to identify the stopped value at \(t\) with
the original value \(M_t\) almost surely.
\end{proof}


\begin{lemma}\label{lem:Martingale.eq_zero_of_predictable_finiteVariation_value_zero}
  \uses{def:Martingale, def:LocallyBoundedVariationOn, lem:Martingale.eq_zero_of_predictable_finiteVariation_past_measurable_zero_increment, lem:LocallyBoundedVariationOn.exists_tendsto_left_univ, lem:Martingale.eq_zero_of_predictable_finiteVariation_bounded_continuous}
  \lean{MeasureTheory.Martingale.eq_zero_of_predictable_finiteVariation_value_zero}
Let \(M\) be a strongly predictable càdlàg true martingale with \(M_0=0\),
and suppose every path has locally bounded variation.  For every
deterministic time \(t>0\), \(M_t=0\) almost surely.
\end{lemma}

\begin{proof}
First remove deterministic predictable jumps.  By
Lemma~\ref{lem:LocallyBoundedVariationOn.exists_tendsto_left_univ}, each
sample path has a left limit at \(t\).  The closed martingale increment
Lemma~\ref{lem:Martingale.eq_zero_of_predictable_finiteVariation_past_measurable_zero_increment}
says that an increment \(M_t-M_s\) vanishes almost surely whenever it is
already \(\mathcal F_s\)-measurable.  Use strong predictability only through
the actual predictable-section or past-sigma-algebra measurability it gives;

